/*
 * A268540  Numbers whose Fouriest transform (see A268236) is 44.
 * https://oeis.org/A268540
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the nth number 4k (k>5) such that for all integer bases b
 *            with 5 ≤ b < sqrt(4k), the representation of 4k in base b
 *            contains at most one digit 4. The sequence is generated by
 *            scanning multiples of 4 and applying this property; results are
 *            cached
 * Range:     u8 n <= 10, u16 n <= 507, u32 n <= 507, u64 n <= 507,
 *            u128 n <= 507, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/floor_sqrt.h"

static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;
static seq_t next_candidate = 24;

seq_t a(idx_t n)
{
    if (n == 0)
        return 0;          /* undefined for n=0, but safe */

    /* Grow the cache until we have at least n terms. */
    while (cache_len < (size_t)n) {
        seq_t m = next_candidate;
        idx_t k = (idx_t)(m / (idx_t)4);  /* k = m/4 */

        bool ok = true;
        idx_t max_base = (k > 5) ? k - 2 : 0;       /* k>5 in all relevant cases */
        idx_t sqrt_m = (idx_t)floor_sqrt(m);
        if (sqrt_m > max_base)
            sqrt_m = max_base;                     /* check only bases ≤ sqrt(m) */

        for (idx_t base = 5; base <= sqrt_m; ++base) {
            seq_t temp = m;
            seq_t base_seq = (seq_t)base;
            int cnt4 = 0;
            while (temp > 0) {
                seq_t digit = temp % base_seq;
                if (digit == (seq_t)4) {
                    if (++cnt4 > 1) {
                        ok = false;
                        break;
                    }
                }
                temp /= base_seq;
            }
            if (!ok)
                break;
        }

        if (ok) {
            if (cache_len == cache_cap) {
                size_t new_cap = (cache_cap) ? cache_cap * 2 : 16;
                seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!new_cache)
                    exit(EXIT_FAILURE);
                cache = new_cache;
                cache_cap = new_cap;
            }
            cache[cache_len++] = m;
        }

        next_candidate += 4;   /* next multiple of 4 */
    }

    return cache[n - 1];
}
